import React, { useState, useEffect } from 'react';

const QuickNotes = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [note, setNote] = useState(localStorage.getItem('quickNote') || '');

  useEffect(() => {
    localStorage.setItem('quickNote', note);
  }, [note]);

  return (
    <div className="position-fixed" style={{ bottom: '20px', left: '20px', zIndex: 1040 }}>
      {isOpen && (
        <div className="card shadow-lg mb-3 slide-up" style={{ width: '280px', border: 'none', background: '#fff9c4', transform: 'rotate(-2deg)' }}>
          <div className="card-header bg-transparent border-0 d-flex justify-content-between align-items-center pb-0">
            <strong className="small text-dark" style={{fontFamily: 'cursive'}}>📝 مفكرة</strong>
            <button type="button" className="btn-close btn-sm" onClick={() => setIsOpen(false)}></button>
          </div>
          <div className="card-body p-2">
            <textarea 
              className="form-control bg-transparent border-0" 
              rows="6" 
              placeholder="سجل أرقام هواتف، مواعيد، أو ملاحظات سريعة هنا..." 
              value={note} 
              onChange={(e) => setNote(e.target.value)}
              style={{ resize: 'none', fontSize: '1rem', fontFamily: 'cursive', color: '#555' }}
            ></textarea>
          </div>
        </div>
      )}
      <button 
        className="btn btn-warning rounded-circle shadow-lg d-flex align-items-center justify-content-center border-2 border-white" 
        style={{ width: '50px', height: '50px', transition: 'transform 0.2s' }}
        onClick={() => setIsOpen(!isOpen)}
        title="ملاحظات سريعة"
      >
        📝
      </button>
    </div>
  );
};

export default QuickNotes;
